Bytes ScriptSession::encodeIndicators(const jass::StableHandleMap& encodeHandle) const {
    constexpr size_t budget=2048;if(!runtime_.snapshotSafe() || failed_ || !world_ || !setupApplied_ || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty())throw std::runtime_error("Indicator snapshot requires a quiescent local session");SnapshotWriter out(budget-64);out.u32(tag("SIND"));out.u32(1);out.text(world_->resources().mapDigest(),64);out.u64(std::bit_cast<std::uint64_t>(simulationTime_));auto next=indicators_.sequence();out.u64(next);std::map<std::pair<NativeKind,std::uint32_t>,std::uint32_t> forward,reverse;auto& entries=indicators_.entries();
    for(size_t i=0;i<entries.size();++i){auto& e=entries[i];if(!e.serial || (std::isfinite(e.started) && simulationTime_>=e.started && simulationTime_-e.started>=1.1)){out.u32(0);continue;}if(!std::isfinite(e.started) || e.started<0 || e.started>simulationTime_ || e.serial>next || next-e.serial>=entries.size() || (e.serial-1)%entries.size()!=i || e.widget<handleBase || e.widget-handleBase>=objects_.size() || !encodeHandle)throw std::runtime_error("Invalid indicator state");auto& object=objects_[e.widget-handleBase];auto kind=object.kind;unsigned type=kind==NativeKind::Unit?1:kind==NativeKind::Item?2:kind==NativeKind::Destructable?3:0;if(!type)throw std::runtime_error("Invalid indicator widget");auto saved=encodeHandle(type==1?"unit":type==2?"item":"destructable",e.widget);auto [a,inserted]=forward.emplace(std::pair{kind,e.widget},saved);auto [b,unique]=reverse.emplace(std::pair{kind,saved},e.widget);if(!saved || (!inserted && a->second!=saved) || (!unique && b->second!=e.widget))throw std::runtime_error("Invalid indicator mapping");out.u32(type);out.u32(saved);out.u32(object.alive?1:0);out.u32(e.color);out.u64(std::bit_cast<std::uint64_t>(e.started));out.u64(e.serial);}return sealSnapshot(out.finish(),budget);
}
void ScriptSession::restoreIndicators(std::span<const std::uint8_t> bytes,const jass::StableHandleMap& decodeHandle) {
    constexpr size_t budget=2048;if(!runtime_.ready() || failed_ || !world_ || !setupApplied_ || mainAttempted_ || !unitRecoveryIncomplete_ || !unitCoreFinished_ || runtime_.threadCount() || !runtime_.inspectExecutions().empty() || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty() || liveObjects(NativeKind::Event))throw std::runtime_error("Indicator restore requires rebuilt widgets before events");Binary in(openSnapshot(bytes,budget));in.expect(tag("SIND"));if(in.u32()!=1 || snapshotText(in,64)!=world_->resources().mapDigest() || snapshotU64(in)!=std::bit_cast<std::uint64_t>(simulationTime_))throw std::runtime_error("Indicator map or clock differs");auto next=snapshotU64(in);std::array<IndicatorState::Entry,8> entries{};std::map<std::pair<NativeKind,std::uint32_t>,std::uint32_t> reverse;
    for(size_t i=0;i<entries.size();++i){auto type=in.u32();if(!type)continue;if(type>3 || !decodeHandle)throw std::runtime_error("Invalid indicator type");auto saved=in.u32(),live=in.u32(),color=in.u32();auto started=std::bit_cast<double>(snapshotU64(in));auto serial=snapshotU64(in);auto kind=type==1?NativeKind::Unit:type==2?NativeKind::Item:NativeKind::Destructable;auto id=decodeHandle(type==1?"unit":type==2?"item":"destructable",saved);auto& identities=type==1?unitIdentityHandles_:type==2?itemIdentityHandles_:destructableIdentityHandles_;auto [it,unique]=reverse.emplace(std::pair{kind,id},saved);if(!saved || live>1 || !id || !identities.contains(saved) || identities.at(saved)!=id || id<handleBase || id-handleBase>=objects_.size() || objects_[id-handleBase].kind!=kind || objects_[id-handleBase].alive!=(live!=0) || (!unique && it->second!=saved) || !std::isfinite(started) || started<0 || started>simulationTime_ || simulationTime_-started>=1.1 || !serial || serial>next || next-serial>=entries.size() || (serial-1)%entries.size()!=i)throw std::runtime_error("Invalid indicator state");entries[i]={id,color,started,serial};}in.finish();indicators_.restore(std::move(entries),next);
}
void ScriptSession::bindIndicatorNatives() {
    auto add=[this](auto& vm,auto a,bool unitOnly){auto id=a[0].bits;if(alive(id,NativeKind::Unit) || (!unitOnly && (alive(id,NativeKind::Item) || alive(id,NativeKind::Destructable)))){auto color=((a[4].bits&255u)<<24)|((a[1].bits&255u)<<16)|((a[2].bits&255u)<<8)|(a[3].bits&255u);indicators_.add(id,color,simulationTime_);}return vm.nothing();};
    bind("UnitAddIndicator","nothing",{"unit","integer","integer","integer","integer"},[add](auto& vm,auto a){return add(vm,a,true);});
    bind("AddIndicator","nothing",{"widget","integer","integer","integer","integer"},[add](auto& vm,auto a){return add(vm,a,false);});
}
